    let mut i = 0
    let mut n = 0
    while i < s.len() {
        let c = s.chars().nth(i).unwrap()
        if c >= bchar(0) && c <= bchar(9) {
            n = n * 10 + (c - bchar(0))
            i = i + 1
        } else {
            return None
        }
    }
    Some(n)
}

